action.new:
if path.stat().st_size > max_file_bytes:
    continue
if len(artifacts) >= max_files:
    break
rel = path.relative_to(root).as_posix()
artifacts.append({"path": rel})

action.old:
if path.stat().st_size > max_file_bytes:
    continue
rel = path.relative_to(root).as_posix()
artifacts.append({"path": rel})
if len(artifacts) >= max_files:
    break
